}", "newString": "/// Extract the tarball basename from a `dist.tarball` URL: the last
/// path segment, with any `?query` and `#fragment` stripped. Returns
/// `None` when the URL ends in a slash or otherwise has no usable last
/// segment.
///
/// This is the segment [`rewrite_tarball_urls`] preserves verbatim in
/// the rewritten public URL, and the one [`resolve_tarball_version`]
/// maps back to the declaring version — so a non-canonical upstream
/// name (one that doesn't follow `<name>-<version>.tgz`) routes the
/// same on the way out and the way back in.
pub fn tarball_basename(url: &str) -> Option<&str> {
    // A URL query starts at `?` and a fragment at `#`; either terminates
    // the path, so cut at whichever comes first.
    let path = url.split(['?', '#']).next().unwrap_or(url);
    let segment = path.rsplit('/').next().unwrap_or(path);
    (!segment.is_empty()).then_some(segment)
}

/// The tarball basename this registry publishes for a version's
/// manifest: the upstream `dist.tarball`'s basename when it has one,
/// else the conventional `<name>-<version>.tgz`. Returns `None` when the
/// manifest carries no string `dist.tarball` to rewrite — such a version
/// has no public tarball route at all.
///
/// The single source of truth shared by [`rewrite_tarball_urls`] (which
/// builds the public URL) and [`resolve_tarball_version`] (which reverses
/// it), so the two can never disagree on a version's tarball name.
fn published_tarball_basename(manifest: &Value, pkg: &PackageName, version: &str) -> Option<String> {
    let tarball = manifest.get("dist").and_then(|dist| dist.get("tarball")).and_then(Value::as_str)?;
    Some(
        tarball_basename(tarball)
            .map(str::to_string)
            .unwrap_or_else(|| pkg.tarball_name_for_version(version)),
    )
}

/// Rewrite every `dist.tarball` in `value` to a URL served by *this*
/// registry instead of whatever URL the source put there. The path
/// stays under `{public_url}/{pkg}/-/…` (so an uplink can't point a
/// manifest at another package's route), but the tarball *basename* is
/// preserved from the upstream URL — a non-canonical name a source
/// chose is served back verbatim. Only when the upstream URL has no
/// usable basename (e.g. it ends in a slash) does the rewrite fall back
/// to the conventional `<name>-<version>.tgz`.
///
/// The version-manifest endpoint calls [`extract_version_manifest`],
/// which applies the same rewrite to its resolved version.
pub fn rewrite_tarball_urls(value: &mut Value, pkg: &PackageName, public_url: &str) {
    let public_url = public_url.trim_end_matches('/');
    if let Some(versions) = value.get_mut("versions").and_then(Value::as_object_mut) {
        for (version, manifest) in versions {
            rewrite_dist_tarball(manifest, pkg, version, public_url);
        }
    }
}

fn rewrite_dist_tarball(value: &mut Value, pkg: &PackageName, version: &str, public_url: &str) {
    let Some(filename) = published_tarball_basename(value, pkg, version) else {
        return;
    };
    let rewritten = format!("{public_url}/{}/-/{filename}", pkg.as_str());
    value
        .get_mut("dist")
        .and_then(Value::as_object_mut)
        .expect("published_tarball_basename returns Some only when dist is an object")
        .insert("tarball".to_string(), Value::String(rewritten));
}

/// Where a tarball request for a given basename routes within a
/// packument, resolved by matching the requested basename against each
/// version's published tarball basename (see [`published_tarball_basename`]).
pub enum TarballRoute<'a> {
    /// Exactly one version publishes this basename; its `dist` block
    /// (integrity, upstream path) governs the request.
    Version(&'a str),
    /// No version publishes this basename.
    Unknown,
    /// Two or more versions publish this same basename, so the request
    /// can't be bound to a single version's integrity — it must be
    /// rejected rather than guessing which version it meant.
    Ambiguous,
}

