/// `dist.tarball` [`rewrite_tarball_urls`] rewrote to it. Binding the
/// route to the declaring version (not to a version parsed out of the
/// filename) keeps an uplink from steering one version's tarball URL at
/// another version's integrity or cache entry, and surfaces a basename
/// that two versions both claim as [`TarballRoute::Ambiguous`].
pub fn resolve_tarball_version<'a>(
    packument: &'a Value,
    pkg: &PackageName,
    filename: &str,
) -> TarballRoute<'a> {
    let Some(versions) = packument.get("versions").and_then(Value::as_object) else {
        return TarballRoute::Unknown;
    };
    let mut matched: Option<&str> = None;
    for (version, manifest) in versions {
        if published_tarball_basename(manifest, pkg, version).as_deref() == Some(filename) {
            if matched.is_some() {
                return TarballRoute::Ambiguous;
            }
            matched = Some(version.as_str());
        }
    }
    matched.map_or(TarballRoute::Unknown, TarballRoute::Version)
